('القرآن', 'hard', 'في أي سورة ورد قوله تعالى: «لَا يَسْتَوِي أَصْحَابُ النَّارِ وَأَصْحَابُ الْجَنَّةِ ۚ أَصْحَابُ الْجَنَّةِ هُمُ الْفَائِزُونَ»؟', '["سورة الحشر", "سورة التغابن", "سورة الصف", "سورة الممتحنة"]'::jsonb, 0, 'بيّن الله أن أصحاب النار وأصحاب الجنة لا يستوون، وأن الفائزين حقاً هم أصحاب الجنة. (المصدر: سورة الحشر، الآية 20)', true),
('السيرة', 'easy', 'ما اسم المسجد الذي أُسري بالنبي ﷺ منه ليلة الإسراء والمعراج؟', '["المسجد الأقصى", "المسجد الحرام", "مسجد قباء", "المسجد النبوي"]'::jsonb, 1, 'قال الله تعالى: «سُبْحَانَ الَّذِي أَسْرَىٰ بِعَبْدِهِ لَيْلًا مِّنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى». (المصدر: سورة الإسراء، الآية 1)', true),
('السيرة', 'easy', 'إلى أي مسجد أُسري بالنبي ﷺ ليلة الإسراء والمعراج؟', '["المسجد النبوي", "مسجد قباء", "المسجد الحرام", "المسجد الأقصى"]'::jsonb, 3, 'أُسري بالنبي ﷺ من المسجد الحرام بمكة إلى المسجد الأقصى ببيت المقدس، ثم عُرج به إلى السماوات. (المصدر: سورة الإسراء، الآية 1)', true),
('السيرة', 'easy', 'من الصحابي الذي قال عنه النبي ﷺ: «لقد كان فيما قبلكم من الأمم محدَّثون، فإن يك في أمتي أحد فإنه عمر»؟', '["أبو بكر الصديق", "عثمان بن عفان", "عمر بن الخطاب", "علي بن أبي طالب"]'::jsonb, 2, 'المحدَّث هو الملهَم الذي يُلقى الصواب في قلبه من غير أن يكون نبياً، وقد خصّ النبي ﷺ عمر بن الخطاب بهذه المنقبة. (المصدر: صحيح البخاري، حديث 3689)', true),
('السيرة', 'easy', 'من أول من بشّر النبي ﷺ بنبوته بعد نزول الوحي عليه في غار حراء؟', '["ورقة بن نوفل", "أبو طالب", "عبد المطلب", "زيد بن حارثة"]'::jsonb, 0, 'لما أخبر النبي ﷺ خديجة بما رأى ذهبت به إلى ورقة بن نوفل، فقال له: هذا الناموس الذي أنزل على موسى، وإنك نبي هذه الأمة. (المصدر: صحيح البخاري، حديث 3)', true),
('السيرة', 'easy', 'من أول من رمى بسهم في سبيل الله؟', '["حمزة بن عبد المطلب", "سعد بن أبي وقاص", "علي بن أبي طالب", "خالد بن الوليد"]'::jsonb, 1, 'قال سعد بن أبي وقاص رضي الله عنه: «إني لأول العرب رمى بسهم في سبيل الله»، وكان ذلك في سرية عبيدة بن الحارث. (المصدر: صحيح البخاري، حديث 3728)', true),
('السيرة', 'easy', 'من الصحابي الذي حفر بئر رومة فبشّره النبي ﷺ بالجنة؟', '["عمر بن الخطاب", "علي بن أبي طالب", "عثمان بن عفان", "طلحة بن عبيد الله"]'::jsonb, 2, 'قال النبي ﷺ: «من يحفر بئر رومة فله الجنة»، فحفرها عثمان بن عفان رضي الله عنه، كما جهّز جيش العسرة في تبوك. (المصدر: صحيح البخاري، حديث 3695)', true),
('السيرة', 'easy', 'ما السورة التي بشّرت بفتح مكة ودخول الناس في دين الله أفواجاً؟', '["سورة الفتح", "سورة الصف", "سورة محمد", "سورة النصر"]'::jsonb, 3, 'قال الله تعالى: «إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ»، ونزلت هذه السورة تبشّر بفتح مكة ودخول الناس في الإسلام أفواجاً. (المصدر: سورة النصر، الآية 1)', true),
('السيرة', 'easy', 'إلى أي جهة كانت قبلة المسلمين قبل أن تُحوَّل إلى الكعبة المشرفة؟', '["بيت المقدس", "المسجد النبوي", "جبل الطور", "مسجد قباء"]'::jsonb, 0, 'كان المسلمون يصلون إلى بيت المقدس أول الأمر، ثم حوّل الله قبلتهم إلى المسجد الحرام، فقال: «فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ». (المصدر: سورة البقرة، الآية 144)', true),
('السيرة', 'easy', 'من هم السابقون الأولون الذين رضي الله عنهم في سورة التوبة؟', '["أهل بدر فقط", "المهاجرون والأنصار", "أهل بيعة الرضوان فقط", "العشرة المبشرون بالجنة فقط"]'::jsonb, 1, 'قال الله تعالى: «وَالسَّابِقُونَ الْأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالْأَنصَارِ وَالَّذِينَ اتَّبَعُوهُم بِإِحْسَانٍ رَّضِيَ اللَّهُ عَنْهُمْ». (المصدر: سورة التوبة، الآية 100)', true),
('السيرة', 'easy', 'ما الذي قاله النبي ﷺ لأبي بكر الصديق وهما في الغار أثناء الهجرة؟', '["اصبر إن الله معنا", "لا تخف إن الله معنا", "لا تحزن إن الله معنا", "توكل على الله"]'::jsonb, 2, 'قال الله تعالى حكاية عن النبي ﷺ: «لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا»، فأنزل الله سكينته على رسوله وأيّده بجنود لم تروها. (المصدر: سورة التوبة، الآية 40)', true),
