('السيرة', 'easy', 'ما السورة التي نزلت في شأن غزوة بني النضير؟', '["سورة الحشر", "سورة الأحزاب", "سورة الفتح", "سورة التوبة"]'::jsonb, 0, 'نزلت سورة الحشر في بني النضير، وافتتحها الله بقوله: «هُوَ الَّذِي أَخْرَجَ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ مِن دِيَارِهِمْ لِأَوَّلِ الْحَشْرِ». (المصدر: سورة الحشر، الآية 2)', true),
('السيرة', 'easy', 'من الصحابي الذي أخذ الراية في غزوة مؤتة بعد استشهاد القادة الثلاثة؟', '["سعد بن أبي وقاص", "خالد بن الوليد", "عمرو بن العاص", "أبو عبيدة بن الجراح"]'::jsonb, 1, 'لما استشهد زيد وجعفر وعبد الله بن رواحة أخذ الراية خالد بن الوليد، فقاتل بها حتى فتح الله على المسلمين. (المصدر: صحيح البخاري، حديث 4262)', true),
('السيرة', 'easy', 'ماذا قال النبي ﷺ عن جبل أحد؟', '["هذا جبل يبغضنا ونبغضه", "هذا جبل من جبال النار", "هذا جبل يحبنا ونحبه", "هذا جبل لا خير فيه"]'::jsonb, 2, 'قال النبي ﷺ لما طلع له جبل أحد: «هذا جبل يحبنا ونحبه»، وهو الجبل الذي وقعت عنده غزوة أحد. (المصدر: صحيح البخاري، حديث 4083)', true),
('السيرة', 'easy', 'من الصحابي الذي قال له النبي ﷺ: «أما ترضى أن تكون مني بمنزلة هارون من موسى»؟', '["جعفر بن أبي طالب", "حمزة بن عبد المطلب", "زيد بن حارثة", "علي بن أبي طالب"]'::jsonb, 3, 'قال النبي ﷺ ذلك لعلي بن أبي طالب حين استخلفه على المدينة في غزوة تبوك، وزاد في رواية مسلم: «غير أنه لا نبي بعدي». (المصدر: صحيح البخاري، حديث 3706)', true),
('السيرة', 'easy', 'ما الذي بشّر به النبي ﷺ أصحاب الشجرة الذين بايعوه تحتها يوم الحديبية؟', '["أنهم لا يدخلون النار", "أنهم يدخلون الجنة بغير حساب", "أنهم أفضل من أهل بدر", "أن لهم أجر مئة شهيد"]'::jsonb, 0, 'قال النبي ﷺ: «لا يدخل النار أحد ممن بايع تحت الشجرة»، وهم أهل بيعة الرضوان الذين رضي الله عنهم. (المصدر: صحيح مسلم، حديث 1856)', true),
('السيرة', 'easy', 'ما السورة التي ذكرت غزوة حنين؟', '["سورة الأنفال", "سورة التوبة", "سورة الأحزاب", "سورة الفتح"]'::jsonb, 1, 'قال الله تعالى: «وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْئًا». (المصدر: سورة التوبة، الآية 25)', true),
('السيرة', 'easy', 'في أي غزوة نزل قوله تعالى: «وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ الرُّسُلُ»؟', '["غزوة بدر", "غزوة الخندق", "غزوة أحد", "غزوة تبوك"]'::jsonb, 2, 'نزلت هذه الآية في غزوة أحد حين أشيع أن النبي ﷺ قُتل، فثبّت الله بها المؤمنين وبيّن أن الرسول بشر يموت كما مات من قبله الرسل. (المصدر: سورة آل عمران، الآية 144)', true),
('السيرة', 'easy', 'بماذا وصف الله تعالى النبي ﷺ في تعامله مع أصحابه بعد غزوة أحد؟', '["بالشدة والغلظة", "بالفظاظة", "بالانفضاض عنهم", "باللين والرحمة"]'::jsonb, 3, 'قال الله تعالى: «فَبِمَا رَحْمَةٍ مِّنَ اللَّهِ لِنتَ لَهُمْ ۖ وَلَوْ كُنتَ فَظًّا غَلِيظَ الْقَلْبِ لَانفَضُّوا مِنْ حَوْلِكَ». (المصدر: سورة آل عمران، الآية 159)', true),
('السيرة', 'easy', 'بماذا وصف الله تعالى النبي ﷺ في سورة الأحزاب ليكون قدوة للمؤمنين؟', '["أسوة حسنة", "ملك كريم", "ساحر عليم", "شاعر مجنون"]'::jsonb, 0, 'قال الله تعالى: «لَّقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ». (المصدر: سورة الأحزاب، الآية 21)', true),
('السيرة', 'easy', 'ما علامة محبة الله تعالى كما بيّنها في سورة آل عمران؟', '["كثرة الصيام", "اتباع النبي ﷺ", "كثرة الصدقة", "الاعتزال في الجبال"]'::jsonb, 1, 'قال الله تعالى: «قُلْ إِن كُنتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ». (المصدر: سورة آل عمران، الآية 31)', true),
('السيرة', 'easy', 'بماذا وصف الله تعالى النبي ﷺ في آخر سورة التوبة؟', '["شديد غليظ القلب", "قاس على المؤمنين", "حريص عليكم رؤوف رحيم", "بعيد عن المؤمنين"]'::jsonb, 2, 'قال الله تعالى: «لَقَدْ جَاءَكُمْ رَسُولٌ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِالْمُؤْمِنِينَ رَءُوفٌ رَّحِيمٌ». (المصدر: سورة التوبة، الآية 128)', true),
('السيرة', 'easy', 'ما الذي سمّاه الله تعالى فتحاً مبيناً في أول سورة الفتح؟', '["فتح مكة", "غزوة بدر", "فتح خيبر", "صلح الحديبية"]'::jsonb, 3, 'قال الله تعالى: «إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا»، والمراد به صلح الحديبية، فقد كان فتحاً عظيماً مهّد لفتح مكة. (المصدر: سورة الفتح، الآية 1)', true),
('السيرة', 'easy', 'ما الوعد الذي بشّر الله به المسلمين في سورة الفتح؟', '["دخول المسجد الحرام آمنين", "فتح بلاد فارس", "فتح القسطنطينية", "دخول المدينة فاتحين"]'::jsonb, 0, 'قال الله تعالى: «لَتَدْخُلُنَّ الْمَسْجِدَ الْحَرَامَ إِن شَاءَ اللَّهُ آمِنِينَ»، فتحقق الوعد بدخول مكة في عمرة القضاء ثم في الفتح. (المصدر: سورة الفتح، الآية 27)', true),
('السيرة', 'medium', 'ما الذي أرسله الله تعالى على الأحزاب في غزوة الخندق ففرّقهم؟', '["المطر الغزير", "الريح الشديدة", "الزلزال العظيم", "الجراد المنتشر"]'::jsonb, 1, 'قال الله تعالى: «فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا»، فقلعت الريح خيامهم وأطفأت نيرانهم فرجعوا خائبين. (المصدر: سورة الأحزاب، الآية 9)', true),
('السيرة', 'medium', 'كيف انتهت غزوة الخندق كما وصفها القرآن الكريم؟', '["بانتصار المسلمين في قتال شديد", "بردّ الله الذين كفروا بغيظهم لم ينالوا خيراً", "باستسلام قريش ودخولها الإسلام", "بدخول المسلمين مكة فاتحين"]'::jsonb, 1, 'قال الله تعالى: «وَرَدَّ اللَّهُ الَّذِينَ كَفَرُوا بِغَيْظِهِمْ لَمْ يَنَالُوا خَيْرًا ۚ وَكَفَى اللَّهُ الْمُؤْمِنِينَ الْقِتَالَ». (المصدر: سورة الأحزاب، الآية 25)', true),
('السيرة', 'medium', 'بماذا وصف القرآن الكريم حال المؤمنين حين جاءهم الأحزاب من فوقهم ومن أسفل منهم؟', '["ناموا مطمئنين آمنين", "فرحوا بالنصر قبل وقوعه", "رجعوا إلى مكة خائفين", "بلغت القلوب الحناجر"]'::jsonb, 3, 'قال الله تعالى: «إِذْ جَاءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ الْأَبْصَارُ وَبَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ». (المصدر: سورة الأحزاب، الآية 10)', true),
('السيرة', 'medium', 'ما الذي فعله النبي ﷺ ليلة بدر قبل القتال؟', '["دعا ربه واستغاث به", "نام حتى طلوع الفجر", "رجع إلى المدينة", "أرسل رسالة صلح إلى قريش"]'::jsonb, 0, 'قال الله تعالى: «إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُم بِأَلْفٍ مِّنَ الْمَلَائِكَةِ مُرْدِفِينَ». (المصدر: سورة الأنفال، الآية 9)', true),
('السيرة', 'medium', 'بماذا سمّى الله تعالى يوم بدر في القرآن الكريم؟', '["يوم الفتح", "يوم الفرقان", "يوم النصر", "يوم الحسم"]'::jsonb, 1, 'قال الله تعالى عن يوم بدر: «يَوْمَ الْفُرْقَانِ يَوْمَ الْتَقَى الْجَمْعَانِ»، لأنه فرّق بين الحق والباطل. (المصدر: سورة الأنفال، الآية 41)', true),
('السيرة', 'medium', 'من الذي رمى التراب في وجوه المشركين يوم بدر؟', '["حمزة بن عبد المطلب", "علي بن أبي طالب", "النبي ﷺ", "سعد بن أبي وقاص"]'::jsonb, 2, 'قال الله تعالى: «وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَٰكِنَّ اللَّهَ رَمَىٰ»، فقد أخذ النبي ﷺ قبضة من التراب فرمى بها وجوه المشركين. (المصدر: سورة الأنفال، الآية 17)', true),
('السيرة', 'medium', 'بماذا وصف الله تعالى المسلمين يوم بدر في قوله: «وَلَقَدْ نَصَرَكُمُ اللَّهُ بِبَدْرٍ وَأَنتُمْ أَذِلَّةٌ»؟', '["كثرة وقوة", "غنى وكثرة مال", "كبر وتجبر", "قلة وضعف في العدد والعدة"]'::jsonb, 3, 'كان المسلمون يوم بدر ثلاثمئة وبضعة عشر رجلاً قليلي العدة، والمشركون نحو ألف، فنصرهم الله مع قلتهم. (المصدر: سورة آل عمران، الآية 123)', true),
('السيرة', 'medium', 'ما السبب الذي ذكره القرآن الكريم لهزيمة المسلمين في غزوة أحد؟', '["مخالفة الرماة أمر النبي ﷺ", "قلة عدد المسلمين", "خيانة المنافقين في المعركة", "نقص السلاح والعتاد"]'::jsonb, 0, 'نزل الرماة من الجبل لجمع الغنائم مخالفين أمر النبي ﷺ، فالتفّ عليهم خالد بن الوليد من خلف الجبل فانقلبت المعركة. (المصدر: سورة آل عمران، الآية 152)', true),
('السيرة', 'medium', 'ما الصفة التي مدح الله بها الأنصار في سورة الحشر؟', '["البخل والإمساك", "الإيثار على أنفسهم", "الحسد والمنافسة", "الكبر والتعالي"]'::jsonb, 1, 'قال الله تعالى عن الأنصار: «وَيُؤْثِرُونَ عَلَىٰ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ»، فآثروا المهاجرين على أنفسهم في المال والمسكن. (المصدر: سورة الحشر، الآية 9)', true),
('السيرة', 'medium', 'بماذا وصف الله تعالى المهاجرين في سورة الحشر؟', '["الأغنياء المقيمون في ديارهم", "التجار الأثرياء", "الفقراء الذين أُخرجوا من ديارهم وأموالهم", "أهل المدينة الأصليون"]'::jsonb, 2, 'قال الله تعالى: «لِلْفُقَرَاءِ الْمُهَاجِرِينَ الَّذِينَ أُخْرِجُوا مِن دِيَارِهِمْ وَأَمْوَالِهِمْ يَبْتَغُونَ فَضْلًا مِّنَ اللَّهِ وَرِضْوَانًا». (المصدر: سورة الحشر، الآية 8)', true),
('السيرة', 'medium', 'من الذين نزل فيهم قوله تعالى: «وَأَنزَلَ الَّذِينَ ظَاهَرُوهُم مِّنْ أَهْلِ الْكِتَابِ مِن صَيَاصِيهِمْ»؟', '["يهود بني قينقاع", "يهود بني النضير", "يهود بني المصطلق", "يهود بني قريظة"]'::jsonb, 3, 'نزلت الآية في يهود بني قريظة الذين ظاهروا الأحزاب على المسلمين في غزوة الخندق ونقضوا عهدهم. (المصدر: سورة الأحزاب، الآية 26)', true),
('السيرة', 'medium', 'ما السورة التي نزلت بعد فترة انقطاع الوحي فطمأنت النبي ﷺ أن ربه ما ودّعه وما قلاه؟', '["سورة الضحى", "سورة الشرح", "سورة العلق", "سورة المدثر"]'::jsonb, 0, 'لما فتر الوحي عن النبي ﷺ فترة نزلت سورة الضحى، وفيها: «مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ». (المصدر: سورة الضحى، الآية 3)', true),
('السيرة', 'medium', 'بأي نداء خاطب الله تعالى نبيه ﷺ في أول سورة المدثر؟', '["يا أيها النبي", "يا أيها المدثر", "يا أيها المزمل", "يا أيها الرسول"]'::jsonb, 1, 'قال الله تعالى: «يَا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنذِرْ»، فأمره بالقيام بالدعوة وإنذار الناس. (المصدر: سورة المدثر، الآية 1)', true),
('السيرة', 'medium', 'في أي يوم نزل قوله تعالى: «الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي»؟', '["يوم فتح مكة", "يوم غزوة بدر", "يوم عرفة في حجة الوداع", "يوم الهجرة إلى المدينة"]'::jsonb, 2, 'نزلت هذه الآية على النبي ﷺ يوم عرفة في حجة الوداع، في السنة العاشرة للهجرة. (المصدر: سورة المائدة، الآية 3)', true),
('السيرة', 'medium', 'ما الذي أعجب المسلمين يوم حنين فلم يغن عنهم شيئاً؟', '["قلة عددهم", "سلاحهم الكثير", "خيولهم السريعة", "كثرتهم"]'::jsonb, 3, 'قال الله تعالى: «وَيَوْمَ حُنَيْنٍ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْئًا وَضَاقَتْ عَلَيْكُمُ الْأَرْضُ بِمَا رَحُبَتْ». (المصدر: سورة التوبة، الآية 25)', true),
('السيرة', 'medium', 'كم سنة كانت مدة الهدنة بين المسلمين وقريش في صلح الحديبية؟', '["عشر سنوات", "خمس سنوات", "عشرون سنة", "سنة واحدة"]'::jsonb, 0, 'وقع صلح الحديبية في السنة السادسة للهجرة على أن توضع الحرب بين الطرفين عشر سنين، وأن يرجع المسلمون عن مكة في عامهم ذلك. (المصدر: صحيح البخاري، حديث 2731)', true),
('السيرة', 'medium', 'من الصحابي الذي تخلّف عن غزوة تبوك ثم تاب الله عليه فكان من الثلاثة الذين خُلّفوا؟', '["حسان بن ثابت", "كعب بن مالك", "أبو لبابة بن عبد المنذر", "عبد الله بن أبي"]'::jsonb, 1, 'تخلّف كعب بن مالك عن تبوك بلا عذر، فأرجأ النبي ﷺ أمره مع صاحبيه خمسين ليلة حتى نزلت توبتهم في سورة التوبة. (المصدر: صحيح البخاري، حديث 4418)', true),
('السيرة', 'medium', 'من أول قائد عيّنه النبي ﷺ على جيش غزوة مؤتة؟', '["جعفر بن أبي طالب", "عبد الله بن رواحة", "زيد بن حارثة", "خالد بن الوليد"]'::jsonb, 2, 'أمّر النبي ﷺ في غزوة مؤتة زيد بن حارثة، وقال: «إن قُتل زيد فجعفر، وإن قُتل جعفر فعبد الله بن رواحة». (المصدر: صحيح البخاري، حديث 4261)', true),
('السيرة', 'medium', 'ما الذي فعله النبي ﷺ حين بلغه خبر استشهاد قادة غزوة مؤتة الثلاثة؟', '["كتم الخبر عن الناس", "أرسل جيشاً آخر في الحال", "صلّى عليهم صلاة الغائب", "نعاهم للناس قبل أن يأتيهم الخبر"]'::jsonb, 3, 'نعى النبي ﷺ زيداً وجعفراً وابن رواحة للناس قبل أن يأتيهم خبرهم، وعيناه تذرفان، ثم أخبرهم أن الراية أخذها سيف من سيوف الله. (المصدر: صحيح البخاري، حديث 4262)', true),
('السيرة', 'medium', 'من الصحابي الذي نزل فيه قوله تعالى: «مَّا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِّن رِّجَالِكُمْ»؟', '["زيد بن حارثة", "علي بن أبي طالب", "جعفر بن أبي طالب", "العباس بن عبد المطلب"]'::jsonb, 0, 'كان زيد بن حارثة يُدعى زيد بن محمد قبل تحريم التبني، فنزلت الآية تنفي أن يكون النبي ﷺ أباً لأحد من الرجال. (المصدر: سورة الأحزاب، الآية 40)', true),
('السيرة', 'medium', 'ما الذي تآمرت عليه قريش في دار الندوة قبل هجرة النبي ﷺ؟', '["مصالحته وإعطاؤه الملك", "قتله أو حبسه أو إخراجه من مكة", "دعوته إلى عبادة الأصنام", "تزويجه من بناتهم"]'::jsonb, 1, 'قال الله تعالى: «وَإِذْ يَمْكُرُ بِكَ الَّذِينَ كَفَرُوا لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ»، فأذن الله لنبيه بالهجرة إلى المدينة. (المصدر: سورة الأنفال، الآية 30)', true),
('السيرة', 'medium', 'فيمن نزل قوله تعالى: «إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلَٰكِنَّ اللَّهَ يَهْدِي مَن يَشَاءُ»؟', '["أبو جهل", "أبو لهب", "أبو طالب عم النبي ﷺ", "أبو سفيان"]'::jsonb, 2, 'نزلت الآية في أبي طالب عم النبي ﷺ، فقد حرص النبي ﷺ على هدايته عند موته فأبى أن يقول لا إله إلا الله. (المصدر: سورة القصص، الآية 56)', true),
('السيرة', 'medium', 'بماذا وصف الله تعالى النبي ﷺ في أول سورة النجم؟', '["ما ضل وما غوى", "ما كذب وما افترى", "ما جهل وما نسي", "ما ظلم وما بغى"]'::jsonb, 3, 'قال الله تعالى: «مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَىٰ»، فنزّه الله نبيه عن الضلال والغواية في قوله وفعله. (المصدر: سورة النجم، الآية 2)', true),
('السيرة', 'medium', 'بماذا ذكّر الله تعالى نبيه ﷺ في سورة الضحى عن حاله في صغره؟', '["أنه كان يتيماً فآواه الله", "أنه كان غنياً فأغناه الله", "أنه كان ملكاً فملّكه الله", "أنه كان قوياً فنصره الله"]'::jsonb, 0, 'قال الله تعالى: «أَلَمْ يَجِدْكَ يَتِيمًا فَآوَىٰ»، فقد مات أبو النبي ﷺ وهو حمل، وماتت أمه وهو ابن ست سنين، فكفله جده ثم عمه. (المصدر: سورة الضحى، الآية 6)', true),
('السيرة', 'medium', 'بماذا ذكّر الله تعالى المسلمين في سورة الأنفال عن حالهم قبل نصر بدر؟', '["بأنهم كانوا أغنياء مقيمين", "بأنهم كانوا قليلاً مستضعفين في الأرض", "بأنهم كانوا ملوكاً وسادة", "بأنهم كانوا كثيري العدد والعدة"]'::jsonb, 1, 'قال الله تعالى: «وَاذْكُرُوا إِذْ أَنتُمْ قَلِيلٌ مُّسْتَضْعَفُونَ فِي الْأَرْضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ النَّاسُ فَآوَاكُمْ وَأَيَّدَكُم بِنَصْرِهِ». (المصدر: سورة الأنفال، الآية 26)', true),
('السيرة', 'hard', 'من هم الثلاثة الذين خُلّفوا عن غزوة تبوك ونزلت توبتهم في سورة التوبة؟', '["كعب بن مالك ومرارة بن الربيع وهلال بن أمية", "كعب بن مالك وحسان بن ثابت وأبو لبابة", "مرارة بن الربيع وهلال بن أمية وسعد بن عبادة", "كعب بن مالك وعبد الله بن أبي وحسان بن ثابت"]'::jsonb, 0, 'قال الله تعالى: «وَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا»، وهم كعب بن مالك ومرارة بن الربيع وهلال بن أمية، وقد هجرهم المسلمون خمسين ليلة حتى تاب الله عليهم. (المصدر: سورة التوبة، الآية 118)', true),
('السيرة', 'hard', 'من الصحابي الذي أرسله النبي ﷺ ليلة الخندق ليأتيه بخبر الأحزاب؟', '["سعد بن معاذ", "حذيفة بن اليمان", "سلمان الفارسي", "عمار بن ياسر"]'::jsonb, 1, 'في ليلة شديدة البرد والريح قال النبي ﷺ: «ألا رجل يأتيني بخبر القوم؟»، فسكت القوم، فقال: «قم يا حذيفة فأتنا بخبر القوم». (المصدر: صحيح مسلم، حديث 1788)', true),
('السيرة', 'hard', 'من الصحابي الذي قتل كعب بن الأشرف اليهودي بعد أن آذى الله ورسوله؟', '["علي بن أبي طالب", "سعد بن معاذ", "محمد بن مسلمة", "عبد الله بن عتيك"]'::jsonb, 2, 'قال النبي ﷺ: «من لكعب بن الأشرف فإنه قد آذى الله ورسوله؟»، فقام محمد بن مسلمة فقتله مع أصحابه ليلاً. (المصدر: صحيح البخاري، حديث 4037)', true),
('السيرة', 'hard', 'في أي غزوة وقعت حادثة الإفك التي نزلت فيها براءة أم المؤمنين عائشة رضي الله عنها؟', '["غزوة بدر", "غزوة أحد", "غزوة تبوك", "غزوة بني المصطلق"]'::jsonb, 3, 'وقعت حادثة الإفك في غزوة بني المصطلق (المريسيع)، حين تخلّفت عائشة رضي الله عنها عن الجيش بسبب عقدها، فتولّى كبر الإفك عبد الله بن أبي. (المصدر: صحيح البخاري، حديث 4141)', true),
('السيرة', 'hard', 'ما الذي أهدته امرأة يهودية للنبي ﷺ في خيبر فأكل منه وكان فيه سم؟', '["شاة مسمومة", "خبز مسموم", "تمر مسموم", "لبن مسموم"]'::jsonb, 0, 'أتت امرأة يهودية النبي ﷺ بشاة مسمومة فأكل منها، فلما سألها عن ذلك قالت: أردت لأقتلك، فقال: «ما كان الله ليسلطك على ذلك». (المصدر: صحيح مسلم، حديث 2190)', true),
('السيرة', 'hard', 'من الصحابي الذي نزل فيه قوله تعالى: «وَمِنَ النَّاسِ مَن يَشْرِي نَفْسَهُ ابْتِغَاءَ مَرْضَاتِ اللَّهِ»؟', '["بلال بن رباح", "صهيب بن سنان الرومي", "عمار بن ياسر", "سلمان الفارسي"]'::jsonb, 1, 'لما أراد صهيب بن سنان الهجرة إلى المدينة منعه المشركون حتى ترك لهم ماله كله، فاشترى نفسه بماله ابتغاء مرضات الله. (المصدر: سورة البقرة، الآية 207)', true),
('السيرة', 'hard', 'فيمن نزل قوله تعالى: «وَسَيُجَنَّبُهَا الْأَتْقَى * الَّذِي يُؤْتِي مَالَهُ يَتَزَكَّىٰ»؟', '["عمر بن الخطاب", "عثمان بن عفان", "أبو بكر الصديق", "علي بن أبي طالب"]'::jsonb, 2, 'نزلت الآيتان في أبي بكر الصديق رضي الله عنه، فقد كان يشتري المستضعفين من المسلمين ويعتقهم، ومنهم بلال بن رباح. (المصدر: سورة الليل، الآية 17)', true),
('السيرة', 'hard', 'ما الدار التي جعلها النبي ﷺ أماناً لمن دخلها يوم فتح مكة؟', '["دار العباس بن عبد المطلب", "دار علي بن أبي طالب", "دار حمزة بن عبد المطلب", "دار أبي سفيان"]'::jsonb, 3, 'قال النبي ﷺ يوم فتح مكة: «من دخل دار أبي سفيان فهو آمن، ومن ألقى السلاح فهو آمن، ومن أغلق بابه فهو آمن». (المصدر: صحيح مسلم، حديث 1780)', true),
('السيرة', 'hard', 'ما الآية التي كان النبي ﷺ يتلوها وهو يطعن الأصنام حول الكعبة يوم فتح مكة؟', '["وَقُلْ جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ", "وَقُلِ الْحَمْدُ لِلَّهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا", "وَمَا رَمَيْتَ إِذْ رَمَيْتَ وَلَٰكِنَّ اللَّهَ رَمَىٰ", "إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا"]'::jsonb, 0, 'كان النبي ﷺ يطعن الأصنام بقوس في يده ويقول: «جاء الحق وزهق الباطل إن الباطل كان زهوقاً»، حتى تطهر البيت منها. (المصدر: سورة الإسراء، الآية 81)', true),
('السيرة', 'hard', 'ما أول سرية بعثها النبي ﷺ بعد الهجرة إلى المدينة؟', '["سرية عبيدة بن الحارث", "سرية حمزة بن عبد المطلب", "سرية عبد الله بن جحش", "سرية زيد بن حارثة"]'::jsonb, 1, 'كانت سرية حمزة بن عبد المطلب إلى سيف البحر في رمضان من السنة الأولى للهجرة أول سرية في الإسلام، وكان لواؤها أبيض وحامله أبو مرثد الغنوي. (المصدر: الطبقات الكبرى لابن سعد، الجزء 2، صفحة 6)', true),
('السيرة', 'hard', 'في أي سنة هجرية كانت غزوة بني قينقاع أول قبائل يهود المدينة التي حاربها النبي ﷺ؟', '["السنة الأولى", "السنة الثالثة", "السنة الثانية", "السنة الرابعة"]'::jsonb, 2, 'حارب النبي ﷺ يهود بني قينقاع في السنة الثانية من الهجرة بعد غزوة بدر، ثم بني النضير في الرابعة، ثم بني قريظة في الخامسة. (المصدر: التفسير والبيان لأحكام القرآن، صفحة 896)', true),
('السيرة', 'hard', 'من الصحابي الذي أخذ سيف النبي ﷺ بحقه يوم أحد؟', '["الزبير بن العوام", "عمر بن الخطاب", "طلحة بن عبيد الله", "أبو دجانة سماك بن خرشة"]'::jsonb, 3, 'عرض النبي ﷺ سيفه يوم أحد وقال: «من يأخذه بحقه؟»، فأحجم القوم، فقال أبو دجانة: «أنا آخذه بحقه»، فأخذه وفلق به هام المشركين. (المصدر: صحيح مسلم، حديث 2470)', true),
('الحديث', 'easy', 'أكمل الحديث: «من صام رمضان ثم أتبعه ستاً من شوال كان...؟»', '["كصيام شهرين", "كصيام سنة واحدة", "كصيام الدهر", "كصيام عشرة أشهر"]'::jsonb, 2, 'صيام رمضان مع ستة أيام من شوال يعدل صيام الدهر، لأن الحسنة بعشر أمثالها فرمضان بعشرة أشهر والستة بستين يوماً. (المصدر: صحيح مسلم، حديث 1164)', true),
('الحديث', 'easy', 'أكمل الحديث: «اقرؤوا القرآن فإنه يأتي يوم القيامة...؟»', '["شفيعاً لأصحابه", "حجة على أعدائه", "نوراً في القبور", "سبباً للرزق"]'::jsonb, 0, 'القرآن يشفع يوم القيامة لمن كان يقرؤه ويعمل به في الدنيا. (المصدر: صحيح مسلم، حديث 804)', true),
('الحديث', 'easy', 'أكمل الحديث: «من دل على خير فله...؟»', '["نصف أجر فاعله", "مثل أجر فاعله", "أجر فاعله مضاعفاً", "أجر الدعوة فقط"]'::jsonb, 1, 'الدال على الخير يأخذ مثل أجر من عمل به من غير أن ينقص من أجر العامل شيء. (المصدر: صحيح مسلم، حديث 1893)', true),
('الحديث', 'easy', 'أكمل الحديث: «من ستر مسلماً...؟»', '["ستره الله في الدنيا فقط", "أثابه الله ببيت في الجنة", "غفر الله له ذنوبه كلها", "ستره الله يوم القيامة"]'::jsonb, 3, 'جزاء من ستر أخاه المسلم في الدنيا أن يستره الله يوم القيامة. (المصدر: صحيح البخاري، حديث 2442)', true),
('الحديث', 'easy', 'أكمل الحديث: «صلوا كما...؟»', '["رأيتموني أصوم", "رأيتموني أصلي", "صلى إبراهيم عليه السلام", "صلى موسى عليه السلام"]'::jsonb, 1, 'أمر النبي ﷺ أن تكون صلاتنا على صفة صلاته التي رآها الصحابة منه. (المصدر: صحيح البخاري، حديث 631)', true),
('الحديث', 'easy', 'أكمل الحديث: «لا صلاة لمن لم يقرأ...؟»', '["بسورة الإخلاص", "بآية الكرسي", "بفاتحة الكتاب", "بالتشهد"]'::jsonb, 2, 'قراءة الفاتحة ركن في كل ركعة من الصلاة، فلا تصح الصلاة بدونها. (المصدر: صحيح البخاري، حديث 756)', true),
('الحديث', 'easy', 'أكمل الحديث: «من قرأ حرفاً من كتاب الله فله به حسنة، والحسنة...؟»', '["بعشر أمثالها", "بسبع أمثالها", "بمئة ضعف", "بألف حسنة"]'::jsonb, 0, 'كل حرف من القرآن بحسنة، والحسنة تضاعف إلى عشر أمثالها. (المصدر: سنن الترمذي، حديث 2910)', true),
('الحديث', 'easy', 'أكمل الحديث: «إذا أتيتم الصلاة فعليكم بالسكينة، فما أدركتم فصلوا، وما فاتكم...؟»', '["فاتركوه", "فأعيدوا الصلاة", "فصلوه في البيت", "فأتموا"]'::jsonb, 3, 'من فاته شيء من الصلاة مع الإمام يصلي ما أدرك ثم يتم ما فاته بعد سلام الإمام. (المصدر: صحيح البخاري، حديث 908)', true),
('الحديث', 'easy', 'أكمل الحديث: «استوصوا...؟»', '["بالأيتام خيراً", "بالنساء خيراً", "بالجيران خيراً", "بالضيوف خيراً"]'::jsonb, 1, 'أوصى النبي ﷺ بالنساء خيراً، وحث على الرفق بهن وحسن معاملتهن. (المصدر: صحيح البخاري، حديث 5186)', true),
('الحديث', 'easy', 'أكمل الحديث: «ما من مولود إلا يولد على...؟»', '["الإسلام", "الإيمان", "الفطرة", "التوحيد"]'::jsonb, 2, 'كل مولود يولد على الفطرة السليمة، ثم أبواه يهودانه أو ينصرانه أو يمجسانه. (المصدر: صحيح البخاري، حديث 1358)', true),
('الحديث', 'easy', 'أكمل الحديث: «من رأى منكم منكراً فليغيره...؟»', '["بيده", "بماله", "بدعائه", "بهجره"]'::jsonb, 0, 'تغيير المنكر يكون باليد لمن قدر عليها، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه. (المصدر: صحيح مسلم، حديث 49)', true),
('الحديث', 'easy', 'أكمل الحديث: «لا يقبل الله صلاة أحدكم إذا أحدث حتى...؟»', '["يتيمم", "يتوضأ", "يغتسل", "يصلي"]'::jsonb, 1, 'من أحدث في أثناء الصلاة أو قبلها وجب عليه الوضوء، ولا تصح صلاته بغير طهور. (المصدر: صحيح البخاري، حديث 135)', true),
('الحديث', 'easy', 'أكمل الحديث: «إن الله طيب لا يقبل إلا...؟»', '["حلالاً", "كثيراً", "طيباً", "خالصاً"]'::jsonb, 2, 'الله طيب لا يقبل من الصدقات والأعمال إلا ما كان طيباً حلالاً. (المصدر: صحيح مسلم، حديث 1015)', true),
('الحديث', 'easy', 'أكمل الحديث: «اليد العليا خير من اليد...؟»', '["السفلى", "اليسرى", "البخيلة", "الممسكة"]'::jsonb, 0, 'اليد العليا هي المنفقة، واليد السفلى هي السائلة، والإنفاق خير من السؤال. (المصدر: صحيح البخاري، حديث 1429)', true),
('الحديث', 'easy', 'أكمل الحديث: «من غدا إلى المسجد أو راح أعد الله له...؟»', '["بيتاً في الجنة", "درجة في الجنة", "قصراً في الجنة", "نزلاً في الجنة"]'::jsonb, 3, 'من ذهب إلى المسجد أو رجع منه أعد الله له ضيافة في الجنة كلما غدا أو راح. (المصدر: صحيح البخاري، حديث 662)', true),
('الحديث', 'easy', 'أكمل الحديث: «الصيام...؟»', '["نور", "جنة", "برهان", "شفاء"]'::jsonb, 1, 'الصيام وقاية للصائم من النار ومن الشهوات، كالجنة التي يتقي بها المحارب. (المصدر: صحيح البخاري، حديث 1894)', true),
('الحديث', 'easy', 'أكمل الحديث: «إذا جاء رمضان فتحت أبواب الجنة وغلقت أبواب...؟»', '["السماء", "الرحمة", "النار", "المساجد"]'::jsonb, 2, 'في رمضان تفتح أبواب الجنة وتغلق أبواب النار وتصفد الشياطين. (المصدر: صحيح البخاري، حديث 1899)', true),
('الحديث', 'easy', 'أكمل الحديث: «من صلى اثنتي عشرة ركعة في يوم وليلة بني له...؟»', '["بيت في الجنة", "قصر في الجنة", "درجة في الجنة", "نهر في الجنة"]'::jsonb, 0, 'السنن الرواتب اثنتا عشرة ركعة في اليوم والليلة، ومن حافظ عليها بنى الله له بيتاً في الجنة. (المصدر: صحيح مسلم، حديث 728)', true),
('الحديث', 'easy', 'أكمل الحديث: «إن الله وتر يحب...؟»', '["الصلاة", "الصيام", "القيام", "الوتر"]'::jsonb, 3, 'الله واحد لا شريك له، ويحب الوتر في الصلاة وغيرها. (المصدر: صحيح البخاري، حديث 6410)', true),
('الحديث', 'easy', 'أكمل الحديث: «يا معشر الشباب من استطاع منكم الباءة...؟»', '["فليصم", "فليتزوج", "فليحج", "فليتصدق"]'::jsonb, 1, 'الزواج أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء. (المصدر: صحيح البخاري، حديث 5066)', true),
