('الفقه', 'medium', 'ما حكم أن يحج شخص عن آخر عاجز عن الحج لكبر أو مرض؟', '["لا يجوز أبداً", "يجوز عن الميت فقط", "يجوز عن الحي فقط", "جائز"]'::jsonb, 3, 'جاءت امرأة من خثعم تسأل عن أبيها الشيخ الكبير الذي لا يثبت على الراحلة، فقال النبي ﷺ: «نعم» أي حجي عنه. (المصدر: صحيح البخاري، حديث 1855)', true),
('الفقه', 'easy', 'ما حكم التلبية في الحج والعمرة؟', '["سنة", "فرض", "حرام", "مكروهة"]'::jsonb, 0, 'التلبية شعار الحاج والمعتمر، وكان النبي ﷺ يلبي بقوله: «لبيك اللهم لبيك، لبيك لا شريك لك لبيك». (المصدر: صحيح البخاري، حديث 1549)', true),
('الفقه', 'medium', 'ما حكم رمي الجمرات في الحج؟', '["سنة فقط", "واجب", "مباح", "مكروه"]'::jsonb, 1, 'رمى النبي ﷺ الجمرات في حجته كما وصف جابر رضي الله عنه مناسك الحج، ورمي الجمار واجب عند جمهور العلماء. (المصدر: صحيح مسلم، حديث 1218)', true),
('الفقه', 'hard', 'ما حكم من ترك طواف الوداع عند مغادرة مكة؟', '["لا شيء عليه", "سنة فاتته", "عليه دم (ذبح شاة)", "يعيد الحج"]'::jsonb, 2, 'قال النبي ﷺ: «لا ينفرن أحد حتى يكون آخر عهده بالبيت»، فطواف الوداع واجب، ومن تركه فعليه دم عند جمهور العلماء. (المصدر: سنن ابن ماجه، حديث 3061)', true),
('الفقه', 'easy', 'ما حكم صلاة ركعتي الطواف بعد الطواف حول الكعبة؟', '["فرض", "حرام", "مكروهة", "سنة"]'::jsonb, 3, 'قال الله: «واتخذوا من مقام إبراهيم مصلى»، فيسن بعد الطواف صلاة ركعتين خلف المقام أو في أي موضع من المسجد. (المصدر: سورة البقرة، الآية 125)', true),
('الفقه', 'medium', 'ما حكم من تجاوز الميقات دون إحرام وهو يريد الحج أو العمرة؟', '["لا يجوز، ويجب أن يحرم من الميقات", "يجوز ويحرم من مكة", "يجوز بلا إحرام", "يجوز إن كان مسافراً"]'::jsonb, 0, 'وقت النبي ﷺ المواقيت وقال: «هن لهن ولمن أتى عليهن من غير أهلهن ممن أراد الحج والعمرة»، فلا يجوز تجاوز الميقات بلا إحرام. (المصدر: صحيح البخاري، حديث 1524)', true),
('الفقه', 'hard', 'ما حكم الجمع بين الصلاتين في عرفة ومزدلفة للحاج؟', '["حرام", "سنة", "مكروه", "واجب على كل حاج"]'::jsonb, 1, 'جمع النبي ﷺ في حجته بين الظهر والعصر بعرفة جمع تقديم، وبين المغرب والعشاء بمزدلفة جمع تأخير، وهو سنة للحاج. (المصدر: صحيح مسلم، حديث 1218)', true),
('الفقه', 'easy', 'ما حكم بيع الإنسان ما لا يملكه؟', '["جائز", "مستحب", "لا يجوز", "مكروه فقط"]'::jsonb, 2, 'قال النبي ﷺ: «لا تبع ما ليس عندك»، فلا يجوز بيع ما لا يملكه البائع ولا يقدر على تسليمه. (المصدر: سنن الترمذي، حديث 1232)', true),
('الفقه', 'medium', 'ما حكم الشفعة للشريك في العقار المشترك غير المقسوم؟', '["حرام", "لا حق له", "مكروهة", "ثابتة مشروعة"]'::jsonb, 3, 'قضى النبي ﷺ بالشفعة في كل ما لم يقسم، فإذا وقعت الحدود وصرفت الطرق فلا شفعة، فيحق للشريك أخذ حصة شريكه بالثمن. (المصدر: صحيح البخاري، حديث 2257)', true),
('الفقه', 'easy', 'ما حكم أكل أموال الناس بالباطل؟', '["جائز", "حرام", "مكروه", "مباح"]'::jsonb, 1, 'نهى الله عن أكل الأموال بالباطل بقوله: «لا تأكلوا أموالكم بينكم بالباطل إلا أن تكون تجارة عن تراض منكم». (المصدر: سورة النساء، الآية 29)', true),
('الفقه', 'medium', 'ما حكم أكل مال اليتيم ظلماً؟', '["جائز", "حرام", "مكروه", "مباح للولي"]'::jsonb, 1, 'قال الله: «إن الذين يأكلون أموال اليتامى ظلماً إنما يأكلون في بطونهم ناراً وسيصلون سعيراً». (المصدر: سورة النساء، الآية 10)', true),
('الفقه', 'hard', 'ما حد القذف (اتهام المحصن بالزنا بلا بينة)؟', '["أربعون جلدة", "مائة جلدة", "ثمانون جلدة", "قطع اليد"]'::jsonb, 2, 'قال الله: «والذين يرمون المحصنات ثم لم يأتوا بأربعة شهداء فاجلدوهم ثمانين جلدة ولا تقبلوا لهم شهادة أبداً». (المصدر: سورة النور، الآية 4)', true),
('الفقه', 'medium', 'ما حكم بيع الذهب بالذهب متفاضلاً (بزيادة أحدهما على الآخر)؟', '["جائز", "مستحب", "مكروه فقط", "حرام وهو ربا الفضل"]'::jsonb, 3, 'قال النبي ﷺ: «لا تبيعوا الذهب بالذهب إلا مثلاً بمثل»، فبيع الذهب بذهب متفاضلاً ربا محرم. (المصدر: صحيح البخاري، حديث 2177)', true),
('الفقه', 'easy', 'ما حكم الزواج لمن استطاع الباءة؟', '["حرام", "سنة مؤكدة", "مكروه", "مباح فقط"]'::jsonb, 1, 'قال النبي ﷺ: «يا معشر الشباب من استطاع منكم الباءة فليتزوج»، فالزواج سنة مؤكدة لمن قدر عليه. (المصدر: صحيح البخاري، حديث 5063)', true),
('الفقه', 'medium', 'ما حكم النكاح بلا ولي عند جمهور العلماء؟', '["صحيح", "لا يصح", "مكروه فقط", "صحيح إن رضيت المرأة"]'::jsonb, 1, 'قال النبي ﷺ: «لا نكاح إلا بولي»، فالولي شرط لصحة النكاح عند جمهور العلماء. (المصدر: سنن الترمذي، حديث 1102)', true),
('الفقه', 'hard', 'ما حكم الوصية بأكثر من ثلث المال؟', '["جائزة دائماً", "مستحبة", "لا تجوز إلا بإذن الورثة", "واجبة"]'::jsonb, 2, 'قال النبي ﷺ لسعد: «الثلث والثلث كثير»، فلا تجوز الوصية بأكثر من الثلث إلا إذا أذن الورثة. (المصدر: صحيح البخاري، حديث 2742)', true),
('الفقه', 'easy', 'متى تنتهي عدة المرأة الحامل المتوفى عنها زوجها؟', '["بعد أربعة أشهر وعشرة أيام", "بعد سنة كاملة", "بعد ثلاثة قروء", "بوضع حملها"]'::jsonb, 3, 'قال الله: «وأولات الأحمال أجلهن أن يضعن حملهن»، فعدة الحامل تنتهي بوضع الحمل. (المصدر: سورة الطلاق، الآية 4)', true),
('الفقه', 'medium', 'ما مدة الرضاعة الكاملة للمولود كما ذكر القرآن؟', '["حولان كاملان", "سنة واحدة", "ثلاث سنوات", "ستة أشهر"]'::jsonb, 0, 'قال الله: «والوالدات يرضعن أولادهن حولين كاملين لمن أراد أن يتم الرضاعة»، فتمام الرضاع حولان. (المصدر: سورة البقرة، الآية 233)', true),
('الفقه', 'easy', 'ما حكم أكل الميتة؟', '["جائز", "حرام", "مكروه", "مستحب"]'::jsonb, 1, 'قال الله: «حرمت عليكم الميتة والدم ولحم الخنزير»، فأكل الميتة حرام إلا للمضطر بقدر الضرورة. (المصدر: سورة المائدة، الآية 3)', true),
('الفقه', 'easy', 'ما حكم صيد البحر للمحرم بالحج أو العمرة؟', '["حرام", "مكروه", "حلال", "واجب"]'::jsonb, 2, 'قال الله: «أحل لكم صيد البحر وطعامه متاعاً لكم وللسيارة وحرم عليكم صيد البر ما دمتم حرماً». (المصدر: سورة المائدة، الآية 96)', true),
('الفقه', 'hard', 'ما حد السرقة في الإسلام؟', '["الجلد", "السجن", "الرجم", "قطع اليد"]'::jsonb, 3, 'قال الله: «والسارق والسارقة فاقطعوا أيديهما جزاء بما كسبا نكالاً من الله». (المصدر: سورة المائدة، الآية 38)', true),
('الفقه', 'medium', 'ما حكم الوفاء بالنذر إذا كان في طاعة الله؟', '["يجب الوفاء به", "مستحب تركه", "حرام الوفاء به", "مكروه"]'::jsonb, 0, 'قال النبي ﷺ: «من نذر أن يطيع الله فليطعه، ومن نذر أن يعصيه فلا يعصه»، فالوفاء بنذر الطاعة واجب. (المصدر: صحيح البخاري، حديث 6696)', true),
('العقيدة', 'easy', 'ما أول دعوة جميع الرسل إلى أقوامهم؟', '["عبادة الله وحده واجتناب الطاغوت", "إقامة الصلاة فقط", "صيام شهر رمضان", "بناء المساجد"]'::jsonb, 0, 'بعث الله في كل أمة رسولاً يدعوهم إلى عبادة الله وحده واجتناب عبادة ما سواه، فالتوحيد أول ما يدعو إليه الرسل. (المصدر: سورة النحل، الآية 36)', true),
('العقيدة', 'easy', 'ما معنى «لا إله إلا الله»؟', '["لا خالق إلا الله", "لا معبود بحق إلا الله", "لا رازق إلا الله", "لا قادر إلا الله"]'::jsonb, 1, 'معناها لا معبود يستحق العبادة إلا الله وحده، فهي نفي للعبادة عن غير الله وإثباتها له وحده. (المصدر: سورة محمد، الآية 19)', true),
('العقيدة', 'easy', 'في كم يوم خلق الله السماوات والأرض؟', '["في يوم واحد", "في ثلاثة أيام", "في ستة أيام", "في عشرة أيام"]'::jsonb, 2, 'خلق الله السماوات والأرض وما بينهما في ستة أيام، وهو على كل شيء قدير، وخلقهما لحكمة عظيمة. (المصدر: سورة الأعراف، الآية 54)', true),
('العقيدة', 'easy', 'ما معنى اسم الله «العزيز»؟', '["الذي يرحم عباده", "الذي يعلم كل شيء", "الذي يرزق خلقه", "الغالب القاهر الذي لا يُغلب"]'::jsonb, 3, 'العزيز هو الغالب الذي لا يُقهر ولا يُغلب، فعزته عزة قوة وقهر وامتناع عن كل نقص. (المصدر: سورة الحشر، الآية 23)', true),
('العقيدة', 'easy', 'من الذي يحيي ويميت؟', '["الله وحده", "الملائكة", "الأنبياء", "الطبيعة"]'::jsonb, 0, 'الإحياء والإماتة بيد الله وحده، فهو الذي يخرج الحي من الميت ويخرج الميت من الحي. (المصدر: سورة البقرة، الآية 258)', true),
('العقيدة', 'easy', 'من الذي يعلم الغيب؟', '["الأنبياء يعلمون الغيب كله", "لا يعلم الغيب إلا الله", "الملائكة يعلمون الغيب", "الأولياء يعلمون الغيب"]'::jsonb, 1, 'الغيب لا يعلمه إلا الله، فلا يعلم ما في السماوات والأرض الغيب إلا هو سبحانه. (المصدر: سورة النمل، الآية 65)', true),
('العقيدة', 'easy', 'ما معنى اسم الله «الملك»؟', '["الذي يرحم عباده", "الذي يغفر الذنوب", "المالك لكل شيء والمتصرف فيه", "الذي يسمع كل شيء"]'::jsonb, 2, 'الملك هو المالك الحقيقي لكل شيء، يتصرف في ملكه كيف يشاء، وملكه لا يزول ولا ينقص. (المصدر: سورة الحشر، الآية 23)', true),
('العقيدة', 'easy', 'ما معنى اسم الله «القدوس»؟', '["كثير العطاء", "الغالب القاهر", "الذي يرزق خلقه", "المنزه عن كل نقص وعيب"]'::jsonb, 3, 'القدوس هو المنزه عن كل نقص وعيب، المطهر عن كل ما لا يليق بجلاله وكماله. (المصدر: سورة الحشر، الآية 23)', true),
('العقيدة', 'easy', 'ما معنى اسم الله «السلام»؟', '["السالم من كل نقص وعيب", "الذي خلق السماوات", "الذي يحيي الموتى", "الذي يملك كل شيء"]'::jsonb, 0, 'السلام هو السالم من كل نقص وعيب، الذي يسلم عباده المؤمنين من الظلم والعذاب. (المصدر: سورة الحشر، الآية 23)', true),
('العقيدة', 'easy', 'ما معنى اسم الله «الجبار»؟', '["الذي يغفر الذنوب", "القاهر فوق عباده الذي يجبر الكسير", "الذي يرزق خلقه", "الذي يسمع الدعاء"]'::jsonb, 1, 'الجبار هو القاهر الذي لا يُقهر، يجبر كسر المنكسرين وينصر المظلومين بقهره وعظمته. (المصدر: سورة الحشر، الآية 23)', true),
('العقيدة', 'easy', 'ما معنى اسم الله «المتكبر»؟', '["كثير العطاء", "الذي يعلم الغيب", "المتعالي عن صفات الخلق ونقائصهم", "الذي يرحم عباده"]'::jsonb, 2, 'المتكبر هو المتعالي عن كل نقص وعيب، والكبرياء والعظمة صفتان خاصتان بالله وحده. (المصدر: سورة الحشر، الآية 23)', true),
('العقيدة', 'easy', 'ما معنى اسم الله «الخالق»؟', '["الذي يغفر الذنوب", "الذي يسمع الأصوات", "الذي يملك كل شيء", "الذي أوجد الأشياء من العدم"]'::jsonb, 3, 'الخالق هو الذي أوجد جميع المخلوقات من العدم على غير مثال سابق، فكل ما سواه مخلوق له. (المصدر: سورة الحشر، الآية 24)', true),
('العقيدة', 'easy', 'ما معنى اسم الله «البارئ»؟', '["الذي برأ الخلق وأوجدهم من العدم", "الذي يرزق العباد", "الذي يحاسب الناس", "الذي يشفي المرضى"]'::jsonb, 0, 'البارئ هو الذي خلق الخلق وأنشأهم من العدم، مبرئاً إياهم من التفاوت والعيب. (المصدر: سورة الحشر، الآية 24)', true),
('العقيدة', 'easy', 'ما معنى اسم الله «المصور»؟', '["الذي يملك كل شيء", "الذي صور المخلوقات على هيئات مختلفة", "الذي يعلم الغيب", "الذي يغفر الذنوب"]'::jsonb, 1, 'المصور هو الذي صور المخلوقات على صور وهيئات مختلفة بحكمته، فلا يشبه مخلوق مخلوقاً آخر في كل صفاته. (المصدر: سورة الحشر، الآية 24)', true),
