('العقيدة', 'easy', 'ما معنى اسم الله «البصير»؟', '["الذي يرزق خلقه", "الذي يغفر الذنوب", "الذي يبصر كل شيء وإن دق وخفي", "الذي يملك كل شيء"]'::jsonb, 2, 'البصير هو الذي يبصر جميع الأشياء، فيرى دبيب النملة السوداء في الليلة الظلماء على الصخرة الصماء. (المصدر: سورة الشورى، الآية 11)', true),
('العقيدة', 'easy', 'ما معنى اسم الله «الحكيم»؟', '["الذي يغفر الذنوب", "الذي يرزق خلقه", "الذي يسمع الدعاء", "الذي يضع الأمور في مواضعها بحكمة وإتقان"]'::jsonb, 3, 'الحكيم هو الذي يضع كل شيء في موضعه، فلا يفعل عبثاً ولا يشرع إلا لحكمة بالغة. (المصدر: سورة لقمان، الآية 27)', true),
('العقيدة', 'easy', 'ما معنى اسم الله «الرحيم»؟', '["ذو الرحمة الواسعة بعباده المؤمنين", "الذي يملك كل شيء", "الذي يعلم الغيب", "الذي يغفر الذنوب فقط"]'::jsonb, 0, 'الرحيم هو ذو الرحمة الخاصة بالمؤمنين في الدنيا والآخرة، فرحمته بهم رحمة توفيق وهداية ونجاة. (المصدر: سورة الفاتحة، الآية 3)', true),
('العقيدة', 'easy', 'ما معنى اسم الله «التواب»؟', '["الذي يرزق خلقه", "الذي يقبل توبة عباده مهما عظمت ذنوبهم", "الذي يعلم الغيب", "الذي يملك كل شيء"]'::jsonb, 1, 'التواب هو الذي يقبل توبة التائبين ويرجع عليهم بالمغفرة، مهما كثرت ذنوبهم إذا صدقوا في التوبة. (المصدر: سورة البقرة، الآية 37)', true),
('العقيدة', 'easy', 'ما معنى اسم الله «الغفور»؟', '["الذي يرزق خلقه", "الذي يسمع الدعاء", "كثير المغفرة لذنوب عباده", "الذي يعلم الغيب"]'::jsonb, 2, 'الغفور هو كثير المغفرة، يستر ذنوب عباده ويتجاوز عنها، ولا يتعاظمه ذنب أن يغفره لمن تاب إليه. (المصدر: سورة الزمر، الآية 53)', true),
('العقيدة', 'easy', 'ما معنى قوله تعالى «مَالِكِ يَوْمِ الدِّينِ»؟', '["مالك الدنيا فقط", "مالك السماوات فقط", "مالك الرزق فقط", "مالك يوم الحساب والجزاء"]'::jsonb, 3, 'مالك يوم الدين هو مالك يوم القيامة، يوم يجازي الله فيه كل نفس بما كسبت، ولا يملك فيه أحد شيئاً إلا بإذنه. (المصدر: سورة الفاتحة، الآية 4)', true),
('العقيدة', 'medium', 'كم عدد أولو العزم من الرسل؟', '["خمسة", "ثلاثة", "سبعة", "عشرة"]'::jsonb, 0, 'أولو العزم خمسة رسل: نوح وإبراهيم وموسى وعيسى ومحمد عليهم الصلاة والسلام، وهم أهل الصبر والثبات في الدعوة. (المصدر: سورة الأحقاف، الآية 35)', true),
('العقيدة', 'medium', 'ما اسم الملكين اللذين أُنزلا ببابل؟', '["جبريل وميكائيل", "هاروت وماروت", "منكر ونكير", "مالك ورضوان"]'::jsonb, 1, 'أنزل الله هاروت وماروت ببابل ابتلاءً للناس، وكانا يعلمان الناس السحر مع التحذير منه وأنه كفر. (المصدر: سورة البقرة، الآية 102)', true),
('العقيدة', 'medium', 'كم عدد خزنة جهنم؟', '["سبعة", "عشرة", "تسعة عشر", "سبعون"]'::jsonb, 2, 'على جهنم تسعة عشر ملكاً من الملائكة الغلاظ الشداد، وهم خزنتها الموكلون بعذاب أهلها. (المصدر: سورة المدثر، الآية 30)', true),
('العقيدة', 'medium', 'ما الكتاب الذي أُنزل على إبراهيم عليه السلام؟', '["التوراة", "الإنجيل", "الزبور", "الصحف"]'::jsonb, 3, 'أنزل الله على إبراهيم عليه السلام صحفاً فيها مواعظ وحكم، كما أنزل صحفاً على موسى عليه السلام. (المصدر: سورة الأعلى، الآية 19)', true),
('العقيدة', 'medium', 'كيف نزل القرآن الكريم على النبي ﷺ؟', '["منجماً مفرقاً على مدى سنوات", "جملة واحدة في ليلة واحدة", "مكتوباً في ألواح", "عن طريق الرؤيا فقط"]'::jsonb, 0, 'نزل القرآن منجماً مفرقاً حسب الوقائع والأحداث، لتثبيت فؤاد النبي ﷺ وتيسير حفظه وفهمه والعمل به. (المصدر: سورة الفرقان، الآية 32)', true),
('العقيدة', 'medium', 'من النبي الذي رفعه الله مكاناً علياً؟', '["موسى عليه السلام", "إدريس عليه السلام", "يوسف عليه السلام", "سليمان عليه السلام"]'::jsonb, 1, 'رفع الله إدريس عليه السلام مكاناً علياً، وهو نبي صديق من أنبياء الله، ورفعه كرامة له. (المصدر: سورة مريم، الآية 57)', true),
('العقيدة', 'medium', 'من النبي الذي أُلقي في النار فكانت برداً وسلاماً؟', '["موسى عليه السلام", "نوح عليه السلام", "إبراهيم عليه السلام", "يونس عليه السلام"]'::jsonb, 2, 'ألقي إبراهيم عليه السلام في النار لكسره الأصنام، فأمر الله النار أن تكون برداً وسلاماً عليه فنجاه الله منها. (المصدر: سورة الأنبياء، الآية 69)', true),
('العقيدة', 'medium', 'من النبي الذي صنع السفينة بأمر الله؟', '["إبراهيم عليه السلام", "موسى عليه السلام", "هود عليه السلام", "نوح عليه السلام"]'::jsonb, 3, 'أمر الله نوحاً عليه السلام أن يصنع السفينة بوحي منه، فحمل فيها المؤمنين وزوجين من كل حيوان ونجوا من الطوفان. (المصدر: سورة هود، الآية 37)', true),
('العقيدة', 'medium', 'من النبي الذي سأل الله ملكاً لا ينبغي لأحد من بعده؟', '["سليمان عليه السلام", "داود عليه السلام", "يوسف عليه السلام", "إبراهيم عليه السلام"]'::jsonb, 0, 'سأل سليمان عليه السلام ربه أن يهبه ملكاً لا ينبغي لأحد من بعده، فأجاب الله دعاءه وسخر له الجن والريح والطير. (المصدر: سورة ص، الآية 35)', true),
('العقيدة', 'medium', 'من النبي الذي أُلقي في الجب وهو صغير؟', '["موسى عليه السلام", "يوسف عليه السلام", "إسماعيل عليه السلام", "يحيى عليه السلام"]'::jsonb, 1, 'ألقى إخوة يوسف عليه السلام أخاهم في غيابة الجب حسداً له، فأنقذه الله وجعله عزيز مصر بعد ذلك. (المصدر: سورة يوسف، الآية 15)', true),
('العقيدة', 'medium', 'كم مقدار يوم القيامة؟', '["ألف سنة", "عشرة آلاف سنة", "خمسون ألف سنة", "مائة ألف سنة"]'::jsonb, 2, 'مقدار يوم القيامة خمسون ألف سنة مما تعدون، وهو يوم عظيم يشق على الكافرين ويسهل على المؤمنين. (المصدر: سورة المعارج، الآية 4)', true),
('العقيدة', 'medium', 'كيف يُحشر الناس يوم القيامة؟', '["بثيابهم وزينتهم", "راكبين على الدواب", "على وجوههم فقط", "حفاة عراة غرلاً"]'::jsonb, 3, 'يُحشر الناس يوم القيامة حفاة بلا نعال، عراة بلا ثياب، غرلاً غير مختونين، كما خلقهم الله أول مرة. (المصدر: صحيح البخاري، حديث 6527)', true),
('العقيدة', 'medium', 'كم عدد الذين يظلهم الله في ظله يوم لا ظل إلا ظله؟', '["سبعة", "ثلاثة", "عشرة", "خمسة"]'::jsonb, 0, 'سبعة يظلهم الله في ظله يوم القيامة، منهم الإمام العادل وشاب نشأ في عبادة الله ورجل قلبه معلق بالمساجد. (المصدر: صحيح البخاري، حديث 660)', true),
('العقيدة', 'medium', 'ما اسم يوم القيامة الوارد في سورة التغابن؟', '["يوم الفصل", "يوم التغابن", "يوم الحساب", "يوم الدين"]'::jsonb, 1, 'سمي يوم القيامة يوم التغابن لأنه يظهر فيه غبن الكافرين بخسارتهم وتفريطهم، وغبن المؤمنين لغيرهم بعلو درجاتهم. (المصدر: سورة التغابن، الآية 9)', true),
('العقيدة', 'medium', 'ما اسم يوم القيامة الوارد في سورة المرسلات؟', '["يوم التغابن", "يوم الحسرة", "يوم الفصل", "يوم الوعيد"]'::jsonb, 2, 'سمي يوم القيامة يوم الفصل لأنه اليوم الذي يفصل الله فيه بين الحق والباطل وبين المؤمنين والكافرين بالحكم العادل. (المصدر: سورة المرسلات، الآية 13)', true),
('العقيدة', 'medium', 'ما أنهار الجنة الأربعة المذكورة في القرآن؟', '["أنهار من ذهب وفضة ولؤلؤ ومرجان", "أنهار من لبن وعسل فقط", "أنهار من خمر وماء فقط", "أنهار من ماء ولبن وخمر وعسل"]'::jsonb, 3, 'في الجنة أنهار من ماء غير آسن، وأنهار من لبن لم يتغير طعمه، وأنهار من خمر لذة للشاربين، وأنهار من عسل مصفى. (المصدر: سورة محمد، الآية 15)', true),
('العقيدة', 'medium', 'كم طول أهل الجنة على صورة أبيهم آدم عليه السلام؟', '["ستون ذراعاً", "ثلاثون ذراعاً", "عشرة أذرع", "مائة ذراع"]'::jsonb, 0, 'خلق الله آدم طوله ستون ذراعاً، ويدخل أهل الجنة على صورته في الطول والجمال، فلا نقص في أجسادهم. (المصدر: صحيح البخاري، حديث 3326)', true),
('العقيدة', 'medium', 'كم عمر أهل الجنة حين يدخلونها؟', '["عشرون سنة", "ثلاث وثلاثون سنة", "أربعون سنة", "ستون سنة"]'::jsonb, 1, 'يدخل أهل الجنة الجنة جرداً مرداً مكحلين أبناء ثلاث وثلاثين سنة، في كمال شبابهم وجمالهم لا يكبرون ولا يهرمون. (المصدر: سنن الترمذي، حديث 2539)', true),
('العقيدة', 'medium', 'كم عدد درجات الجنة؟', '["سبع درجات", "خمسون درجة", "مائة درجة", "ألف درجة"]'::jsonb, 2, 'في الجنة مائة درجة أعدها الله للمجاهدين في سبيله، ما بين الدرجتين كما بين السماء والأرض. (المصدر: صحيح البخاري، حديث 2790)', true),
('العقيدة', 'medium', 'ما معنى إحصاء أسماء الله الحسنى في الحديث «من أحصاها دخل الجنة»؟', '["حفظ عددها فقط", "كتابتها على ورق", "ترديدها بلا فهم", "حفظها وفهم معانيها والعمل بمقتضاها"]'::jsonb, 3, 'إحصاء أسماء الله الحسنى يكون بحفظها وفهم معانيها والتعبد لله بها، لا بمجرد عدها وحفظ ألفاظها. (المصدر: صحيح البخاري، حديث 2736)', true),
('العقيدة', 'medium', 'ما حكم الحلف بغير الله تعالى؟', '["شرك أصغر", "مباح", "مستحب", "مكروه فقط"]'::jsonb, 0, 'الحلف بغير الله من الشرك الأصغر، لأن الحلف تعظيم ولا يكون إلا بالله، ومن حلف بغير الله فقد أشرك. (المصدر: سنن الترمذي، حديث 1535)', true),
('العقيدة', 'medium', 'ما حكم التطير وهو التشاؤم بالطيور ونحوها؟', '["مباح", "شرك", "مستحب", "واجب"]'::jsonb, 1, 'التطير شرك لأنه اعتقاد أن غير الله يجلب الضر أو يدفعه، والمؤمن يتوكل على الله ولا يتشاءم بشيء. (المصدر: سنن أبي داود، حديث 3910)', true),
('العقيدة', 'medium', 'ما حكم تعليق التمائم لدفع الضر وجلب النفع؟', '["مباح", "مستحب", "شرك", "واجب"]'::jsonb, 2, 'من تعلق تميمة فقد أشرك، لأن دفع الضر وجلب النفع بيد الله وحده، وتعليقها اعتقاد النفع في غير الله. (المصدر: مسند أحمد، حديث 17422)', true),
('العقيدة', 'medium', 'ما حكم تعلم السحر والعمل به؟', '["مباح", "مكروه", "مستحب", "كفر"]'::jsonb, 3, 'السحر كفر بالله، فقد تعلم الناس السحر من الشياطين وهاروت وماروت، ومن يعمل به فقد كفر بما أنزل على محمد ﷺ. (المصدر: سورة البقرة، الآية 102)', true),
('العقيدة', 'medium', 'ما جزاء من أتى عرافاً فسأله عن شيء من الغيب؟', '["لا تقبل له صلاة أربعين ليلة", "تقبل صلاته كاملة", "يؤجر على سؤاله", "لا شيء عليه"]'::jsonb, 0, 'من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين ليلة، لأن الغيب لا يعلمه إلا الله، وسؤال العرافين طريق إلى الشرك. (المصدر: صحيح مسلم، حديث 2230)', true),
('العقيدة', 'hard', 'كم عدد أجنحة جبريل عليه السلام؟', '["مائة جناح", "ستمائة جناح", "ألف جناح", "سبعون جناحاً"]'::jsonb, 1, 'رأى النبي ﷺ جبريل عليه السلام على صورته الحقيقية وله ستمائة جناح قد سد الأفق، فهو أعظم الملائكة خلقة. (المصدر: صحيح البخاري، حديث 3232)', true),
('العقيدة', 'hard', 'من الملك الذي عرض على النبي ﷺ أن يطبق على أهل مكة الأخشبين؟', '["جبريل عليه السلام", "ميكائيل عليه السلام", "ملك الجبال", "إسرافيل عليه السلام"]'::jsonb, 2, 'بعد أن آذى أهل الطائف النبي ﷺ جاءه ملك الجبال وعرض عليه أن يطبق عليهم الأخشبين، فرفض النبي رجاء أن يخرج الله من أصلابهم من يعبد الله وحده. (المصدر: صحيح البخاري، حديث 3231)', true),
('العقيدة', 'hard', 'كم عدد أهل النار من كل ألف يوم القيامة؟', '["مائة", "خمسمائة", "تسعمائة", "تسعمائة وتسعة وتسعون"]'::jsonb, 3, 'يقال لآدم يوم القيامة: أخرج بعث النار من ذريتك، فيخرج من كل ألف تسعمائة وتسعة وتسعون إلى النار وواحد إلى الجنة. (المصدر: صحيح البخاري، حديث 3348)', true),
('العقيدة', 'hard', 'من أول من يُكسى يوم القيامة؟', '["إبراهيم عليه السلام", "محمد ﷺ", "موسى عليه السلام", "آدم عليه السلام"]'::jsonb, 0, 'أول من يكسى يوم القيامة إبراهيم عليه السلام، كرامة له لما تجرد لله حين ألقي في النار. (المصدر: صحيح البخاري، حديث 3349)', true),
('العقيدة', 'hard', 'ما أول طعام يأكله أهل الجنة؟', '["ثمار الجنة", "زيادة كبد الحوت", "لحم طير", "عسل مصفى"]'::jsonb, 1, 'أول طعام يأكله أهل الجنة زيادة كبد الحوت، وهي قطعة زائدة في كبد الحوت من أطيب الطعام. (المصدر: صحيح البخاري، حديث 3329)', true),
('العقيدة', 'hard', 'ما أول ما يُقضى بين الناس فيه يوم القيامة؟', '["الصلاة", "الزكاة", "الدماء", "الأموال"]'::jsonb, 2, 'أول ما يقضى بين الناس يوم القيامة في الدماء، لعظم حرمة الدماء وخطورة سفكها بغير حق. (المصدر: صحيح البخاري، حديث 6533)', true),
('العقيدة', 'hard', 'ما الحساب اليسير يوم القيامة؟', '["الميزان", "الصراط", "الحوض", "العرض"]'::jsonb, 3, 'الحساب اليسير هو العرض، بأن تعرض الأعمال على العبد فيقر بها ويتجاوز الله عنه، أما من نوقش الحساب وعُدت عليه سيئاته فقد عُذب. (المصدر: صحيح البخاري، حديث 4939)', true),
('العقيدة', 'hard', 'ما «الوسيلة» التي أمر النبي ﷺ أمته أن يسألوها له؟', '["منزلة في الجنة لا تنبغي إلا لعبد واحد", "باب من أبواب الجنة", "نهر في الجنة", "شجرة في الجنة"]'::jsonb, 0, 'الوسيلة منزلة رفيعة في الجنة لا تنبغي إلا لعبد واحد من عباد الله، ويرجو النبي ﷺ أن يكون هو ذلك العبد. (المصدر: صحيح مسلم، حديث 384)', true),
('العقيدة', 'hard', 'من أهون أهل النار عذاباً؟', '["فرعون", "أبو طالب", "أبو لهب", "أبو جهل"]'::jsonb, 1, 'أهون أهل النار عذاباً أبو طالب، يوضع في أخمص قدميه جمرتان يغلي منهما دماغه، مع أنه كان يحمي النبي ﷺ لكنه مات على الكفر. (المصدر: صحيح مسلم، حديث 210)', true),
('العقيدة', 'hard', 'كم سنة يهوي الحجر في جهنم حتى يبلغ قعرها؟', '["عشر سنوات", "أربعون سنة", "سبعون سنة", "مائة سنة"]'::jsonb, 2, 'سمع الصحابة وجبة عظيمة فأخبرهم النبي ﷺ أنها حجر ألقي في جهنم منذ سبعين سنة وهو يهوي حتى بلغ قعرها، لبيان عمق جهنم وعظمها. (المصدر: صحيح مسلم، حديث 2844)', true),
