('التاريخ', 'medium', 'من السلطان المملوكي الذي خلف قطز في الحكم بعد معركة عين جالوت؟', '["الظاهر بيبرس", "عز الدين أيبك", "المنصور قلاوون", "الناصر محمد"]'::jsonb, 0, 'تولى الظاهر بيبرس السلطنة بعد مقتل قطز سنة 658هـ عقب انتصار المسلمين على المغول في عين جالوت، وحكم مصر والشام سبع عشرة سنة. (المصدر: السلوك لمعرفة دول الملوك للمقريزي، أحداث سنة 658هـ)', true),
('التاريخ', 'medium', 'من السلطان العثماني الذي قضى على الدولة المملوكية في مصر والشام؟', '["محمد الفاتح", "سليم الأول", "سليمان القانوني", "بايزيد الثاني"]'::jsonb, 1, 'قضى السلطان سليم الأول على الدولة المملوكية بعد انتصاره في معركة مرج دابق سنة 922هـ ومعركة الريدانية سنة 923هـ، فدخلت مصر والشام في حكم العثمانيين. (المصدر: تاريخ الدولة العثمانية لمحمد فريد بك، الجزء 1)', true),
('التاريخ', 'medium', 'من الذي أسس مدينة مراكش؟', '["عبد الله بن ياسين", "عبد المؤمن بن علي", "أبو بكر بن عمر", "يوسف بن تاشفين"]'::jsonb, 3, 'أسس يوسف بن تاشفين مدينة مراكش سنة 454هـ وجعلها عاصمة دولة المرابطين، وبقيت من أشهر مدن المغرب إلى اليوم. (المصدر: البيان المغرب لابن عذاري، الجزء 4)', true),
('التاريخ', 'medium', 'من الذي لُقّب بصقر قريش؟', '["عبد الرحمن الناصر", "هشام بن عبد الرحمن", "عبد الرحمن الداخل", "الحكم بن هشام"]'::jsonb, 2, 'لُقّب عبد الرحمن الداخل بصقر قريش، وهو مؤسس الدولة الأموية في الأندلس، وقد أطلق عليه الخليفة العباسي المنصور هذا اللقب إعجاباً بذكائه وشجاعته. (المصدر: نفح الطيب للمقري، المجلد 1)', true),
('التاريخ', 'medium', 'من الذي بنى مدينة الزهراء قرب قرطبة؟', '["عبد الرحمن الناصر", "عبد الرحمن الداخل", "هشام بن عبد الرحمن", "محمد بن عبد الرحمن"]'::jsonb, 0, 'بنى عبد الرحمن الناصر مدينة الزهراء قرب قرطبة سنة 325هـ لتكون مقراً للخلافة الأموية في الأندلس، وسماها باسم جاريته الزهراء. (المصدر: نفح الطيب للمقري، المجلد 1)', true),
('التاريخ', 'medium', 'من الخليفة الفاطمي الذي أُسست مدينة القاهرة في عهده؟', '["المنصور بالله", "المعز لدين الله", "العزيز بالله", "الحاكم بأمر الله"]'::jsonb, 1, 'أُسست مدينة القاهرة في عهد الخليفة الفاطمي المعز لدين الله، إذ أمر قائده جوهر الصقلي ببنائها سنة 358هـ لتكون عاصمة جديدة للدولة الفاطمية. (المصدر: الخطط للمقريزي، الجزء 1)', true),
('التاريخ', 'medium', 'في أي سنة هجرية بدأ بناء الجامع الأزهر؟', '["358هـ", "361هـ", "359هـ", "362هـ"]'::jsonb, 2, 'بدأ جوهر الصقلي بناء الجامع الأزهر في جمادى الأولى سنة 359هـ بأمر الخليفة المعز لدين الله، وأُقيمت فيه أول جمعة في رمضان سنة 361هـ. (المصدر: الخطط للمقريزي، الجزء 2)', true),
('التاريخ', 'medium', 'من العالم المسلم الذي اكتشف الدورة الدموية الصغرى؟', '["ابن سينا", "الرازي", "الزهراوي", "ابن النفيس"]'::jsonb, 3, 'ابن النفيس هو العالم المسلم الذي اكتشف الدورة الدموية الصغرى بين القلب والرئتين، وذلك قبل اكتشافها في أوروبا بقرون. (المصدر: عيون الأنباء في طبقات الأطباء لابن أبي أصيبعة، ترجمة ابن النفيس)', true),
('التاريخ', 'medium', 'من العالم المسلم صاحب كتاب «المناظر» في علم البصريات؟', '["ابن الهيثم", "الخوارزمي", "البيروني", "ابن رشد"]'::jsonb, 0, 'ابن الهيثم هو صاحب كتاب المناظر في علم البصريات، وشرح فيه كيفية الإبصار وطبيعة الضوء، ويُعد مؤسس علم البصريات الحديث. (المصدر: عيون الأنباء في طبقات الأطباء لابن أبي أصيبعة، ترجمة ابن الهيثم)', true),
('التاريخ', 'medium', 'من الفيلسوف المسلم صاحب كتاب «المدينة الفاضلة»؟', '["ابن سينا", "الكندي", "ابن رشد", "الفارابي"]'::jsonb, 3, 'الفارابي هو الفيلسوف المسلم صاحب كتاب آراء أهل المدينة الفاضلة، ويُلقب بالمعلم الثاني بعد أرسطو. (المصدر: سير أعلام النبلاء للذهبي، ترجمة الفارابي)', true),
('التاريخ', 'medium', 'من مؤلف كتاب «فتح الباري شرح صحيح البخاري»؟', '["النووي", "ابن حجر العسقلاني", "ابن كثير", "السيوطي"]'::jsonb, 1, 'ابن حجر العسقلاني هو مؤلف كتاب فتح الباري شرح صحيح البخاري، وهو أشهر شروح صحيح البخاري وأوسعها. (المصدر: شذرات الذهب لابن العماد الحنبلي، المجلد 7)', true),
('التاريخ', 'medium', 'من مؤلف كتاب «الجامع لأحكام القرآن»؟', '["ابن كثير", "الطبري", "الزمخشري", "القرطبي"]'::jsonb, 3, 'الإمام القرطبي هو مؤلف كتاب الجامع لأحكام القرآن، وهو تفسير جامع بين التفسير والفقه والأحكام. (المصدر: سير أعلام النبلاء للذهبي، ترجمة القرطبي)', true),
('التاريخ', 'medium', 'من مؤلف كتاب «سنن الترمذي»؟', '["أبو عيسى الترمذي", "أبو داود السجستاني", "أحمد بن شعيب النسائي", "محمد بن يزيد ابن ماجه"]'::jsonb, 0, 'أبو عيسى الترمذي هو مؤلف كتاب سنن الترمذي، وهو أحد الكتب الستة في الحديث، ويُعرف باسم الجامع الصحيح. (المصدر: سير أعلام النبلاء للذهبي، ترجمة الترمذي)', true),
('التاريخ', 'medium', 'من مؤلف كتاب «الرسالة» في أصول الفقه؟', '["الشافعي", "أبو حنيفة", "مالك بن أنس", "أحمد بن حنبل"]'::jsonb, 0, 'الإمام الشافعي هو مؤلف كتاب الرسالة في أصول الفقه، وهو أول كتاب جامع في علم أصول الفقه، وإليه يُنسب المذهب الشافعي. (المصدر: سير أعلام النبلاء للذهبي، ترجمة الشافعي)', true),
('التاريخ', 'hard', 'في أي سنة هجرية فُتحت مدينة سمرقند؟', '["90هـ", "93هـ", "96هـ", "99هـ"]'::jsonb, 1, 'فتح قتيبة بن مسلم مدينة سمرقند سنة 93هـ بعد حصار شديد، فكانت من أعظم مدن ما وراء النهر، ومنها انتشر الإسلام في آسيا الوسطى. (المصدر: تاريخ الطبري، أحداث سنة 93هـ)', true),
('التاريخ', 'hard', 'من قائد المسلمين في معركة نهاوند؟', '["سعد بن أبي وقاص", "خالد بن الوليد", "أبو موسى الأشعري", "النعمان بن مقرن"]'::jsonb, 3, 'قاد النعمان بن مقرن المسلمين في معركة نهاوند سنة 21هـ الملقبة بفتح الفتوح، واستشهد فيها بعد أن تحقق النصر على الفرس. (المصدر: تاريخ الطبري، أحداث سنة 21هـ)', true),
('التاريخ', 'hard', 'من الخليفة العباسي الذي فتح مدينة عمورية سنة 223هـ؟', '["المعتصم بالله", "المأمون", "هارون الرشيد", "المتوكل على الله"]'::jsonb, 0, 'فتح الخليفة العباسي المعتصم بالله مدينة عمورية سنة 223هـ بعد أن استنجدت به امرأة مسلمة، فلبى نداءها ودمر أمنع حصون الروم. (المصدر: البداية والنهاية لابن كثير، أحداث سنة 223هـ)', true),
('التاريخ', 'hard', 'من القائد الذي فتح جزيرة قبرص سنة 28هـ؟', '["عمرو بن العاص", "عبد الله بن سعد", "معاوية بن أبي سفيان", "عبد الله بن قيس"]'::jsonb, 2, 'فتح معاوية بن أبي سفيان جزيرة قبرص سنة 28هـ في عهد عثمان بن عفان، وكانت أول غزوة بحرية للمسلمين في البحر المتوسط. (المصدر: تاريخ الطبري، أحداث سنة 28هـ)', true),
('التاريخ', 'hard', 'من السلطان المملوكي الذي حرر عكا من الصليبيين سنة 690هـ؟', '["الظاهر بيبرس", "الأشرف خليل بن قلاوون", "المنصور قلاوون", "الناصر محمد بن قلاوون"]'::jsonb, 1, 'حرر السلطان المملوكي الأشرف خليل بن قلاوون مدينة عكا من الصليبيين سنة 690هـ، فكانت آخر معاقلهم في الشام، وانتهى بها الوجود الصليبي في المشرق. (المصدر: السلوك لمعرفة دول الملوك للمقريزي، أحداث سنة 690هـ)', true),
('التاريخ', 'hard', 'من السلطان العثماني الذي استشهد في معركة كوسوفو سنة 791هـ؟', '["بايزيد الأول", "أورخان غازي", "عثمان بن أرطغرل", "مراد الأول"]'::jsonb, 3, 'استشهد السلطان مراد الأول في معركة كوسوفو سنة 791هـ بعد انتصار العثمانيين على الصرب، وهو السلطان العثماني الوحيد الذي قُتل في أرض المعركة. (المصدر: تاريخ الدولة العثمانية لمحمد فريد بك، الجزء 1)', true),
('التاريخ', 'hard', 'من مؤسس دولة المغول المسلمين في الهند؟', '["بابر", "شاه جهان", "أكبر", "همايون"]'::jsonb, 0, 'بابر هو مؤسس دولة المغول المسلمين في الهند، أسسها بعد انتصاره في معركة بانيبات سنة 932هـ، ومن سلالته شاه جهان باني تاج محل. (المصدر: الموسوعة التاريخية للدرر السنية، أحداث سنة 932هـ)', true),
('التاريخ', 'hard', 'من مؤلف كتاب «الكامل في التاريخ»؟', '["الطبري", "ابن خلدون", "ابن الأثير", "ابن كثير"]'::jsonb, 2, 'ابن الأثير هو مؤلف كتاب الكامل في التاريخ، وهو من أشهر كتب التاريخ الإسلامي، رتب فيه الأحداث سنة بعد سنة من بداية الخلق إلى عصره. (المصدر: وفيات الأعيان لابن خلكان، ترجمة ابن الأثير)', true),
('التاريخ', 'hard', 'من مؤلف كتاب «تاريخ بغداد»؟', '["ابن عساكر", "الخطيب البغدادي", "ابن الجوزي", "الذهبي"]'::jsonb, 1, 'الخطيب البغدادي هو مؤلف كتاب تاريخ بغداد، وهو موسوعة في تراجم علماء بغداد وأخبارها، جمع فيه تراجم نحو ثمانية آلاف عالم. (المصدر: سير أعلام النبلاء للذهبي، ترجمة الخطيب البغدادي)', true),
('التاريخ', 'hard', 'من مؤلف كتاب «وفيات الأعيان وأنباء أبناء الزمان»؟', '["ابن الأثير", "ابن الجوزي", "الذهبي", "ابن خلكان"]'::jsonb, 3, 'ابن خلكان هو مؤلف كتاب وفيات الأعيان وأنباء أبناء الزمان، وهو من أشهر كتب التراجم، جمع فيه تراجم العلماء والملوك والأدباء. (المصدر: سير أعلام النبلاء للذهبي، ترجمة ابن خلكان)', true),
('التاريخ', 'hard', 'من مؤسس علم النحو؟', '["سيبويه", "الخليل بن أحمد", "أبو الأسود الدؤلي", "الكسائي"]'::jsonb, 2, 'أبو الأسود الدؤلي هو مؤسس علم النحو، وضع أصوله بأمر علي بن أبي طالب، كما وضع النقط على المصحف لضبط قراءته. (المصدر: سير أعلام النبلاء للذهبي، ترجمة أبي الأسود الدؤلي)', true),
('التاريخ', 'hard', 'من مؤسس علم العروض؟', '["الخليل بن أحمد الفراهيدي", "أبو الأسود الدؤلي", "سيبويه", "الزمخشري"]'::jsonb, 0, 'الخليل بن أحمد الفراهيدي هو مؤسس علم العروض الذي تُوزن به أشعار العرب، وهو أيضاً صاحب أول معجم عربي وهو كتاب العين. (المصدر: سير أعلام النبلاء للذهبي، ترجمة الخليل بن أحمد)', true);
